## Usage

```typescript
import normalizeRegistries from '@pnpm/config.normalize-registries'

normalizeRegistries({
  'default': 'https://registry.npmjs.org',
  '@foo': 'https://example.com',
})
// will return the same object but the URLs will end with a /
```

## Usage

<!--@example('./example.js')-->
```js
'use strict'
const createResolveFromNpm = require('@pnpm/resolving.npm-resolver').default

const resolveFromNpm = createResolveFromNpm({
  store: '.store',
  offline: false,
  rawConfig: {
    registry: 'https://registry.npmjs.org/',
  },
})

resolveFromNpm({alias: 'is-positive', bareSpecifier: '1.0.0'}, {
  registry: 'https://registry.npmjs.org/',
})
.then(resolveResult => console.log(JSON.stringify(resolveResult, null, 2)))
